void HAL_SPI_TxRxCpltCallback(SPI_HandleTypeDef *hspi){
	if (hspi == IMU_INTERFACE){ // These events refer to the IMU SPI DMA.
		IMU_TxRxCpltCallback();
	}
	if (hspi == ALT_INTERFACE){
		ALT_TxRxCpltCallback();
	}
}

void IMU_TxRxCpltCallback(){
	HAL_GPIO_WritePin(IMU_CS_GPIO_Port, IMU_CS_Pin, GPIO_PIN_SET);
	switch(IMU_Current_DMA_Transaction) {
		case IMU_WRITE_REG:
			break; // No additional processing is required on register write.
		case IMU_SINGLE_REG:
			break; // Not used yet (all single register reads use blocking mode)
		case IMU_PACKET: // Parse IMU Packet
			IMU_Raw.A_X = (IMU_SPI_IMUPacket_RX[IMU_OUTX_H_A-0x21] << 8) + IMU_SPI_IMUPacket_RX[IMU_OUTX_L_A-0x21];
			IMU_Raw.A_Y = (IMU_SPI_IMUPacket_RX[IMU_OUTY_H_A-0x21] << 8) + IMU_SPI_IMUPacket_RX[IMU_OUTY_L_A-0x21];
			IMU_Raw.A_Z = (IMU_SPI_IMUPacket_RX[IMU_OUTZ_H_A-0x21] << 8) + IMU_SPI_IMUPacket_RX[IMU_OUTZ_L_A-0x21];

			IMU_Raw.G_X = (IMU_SPI_IMUPacket_RX[IMU_OUTX_H_G-0x21] << 8) + IMU_SPI_IMUPacket_RX[IMU_OUTX_L_G-0x21];
			IMU_Raw.G_Y = (IMU_SPI_IMUPacket_RX[IMU_OUTY_H_G-0x21] << 8) + IMU_SPI_IMUPacket_RX[IMU_OUTY_L_G-0x21];
			IMU_Raw.G_Z = (IMU_SPI_IMUPacket_RX[IMU_OUTZ_H_G-0x21] << 8) + IMU_SPI_IMUPacket_RX[IMU_OUTZ_L_G-0x21];

			IMU_Data.A_X = IMU_Raw.A_X * 0.976f - IMU_Bias.A_X;	// Scaling factor comes from "Linear
			IMU_Data.A_Y = IMU_Raw.A_Y * 0.976f - IMU_Bias.A_Y;	// acceleration sensitivity", p.12 on datasheet
			IMU_Data.A_Z = IMU_Raw.A_Z * 0.976f - IMU_Bias.A_Z;

			IMU_Data.G_X = IMU_Raw.G_X * 0.07f - IMU_Bias.G_X;	// Scaling factor comes from "Angular
			IMU_Data.G_Y = IMU_Raw.G_Y * 0.07f - IMU_Bias.G_Y;	// rate sensitivity", p.12 on datasheet
			IMU_Data.G_Z = IMU_Raw.G_Z * 0.07f - IMU_Bias.G_Z;

			IMU_Angles.G_X += IMU_Data.G_X / 1920.0f;	// Integrate rates
			IMU_Angles.G_Y += IMU_Data.G_Y / 1920.0f;
			IMU_Angles.G_Z += IMU_Data.G_Z / 1920.0f;

			attitude_accel.roll = atan2f(IMU_Data.A_Y, IMU_Data.A_Z);
			attitude_accel.roll *= RAD_TO_DEG;
			attitude.roll += IMU_Data.G_X*0.000520833f;//1/1920
			attitude.roll = IMU_FILTER_COEFFICIENT * attitude.roll + (1-IMU_FILTER_COEFFICIENT) *
					attitude_accel.roll;		// Complementary filter for roll

			attitude_accel.pitch = atan2f(-IMU_Data.A_X, sqrtf(IMU_Data.A_Y*IMU_Data.A_Y + IMU_Data.A_Z*IMU_Data.A_Z));
			attitude_accel.pitch *= RAD_TO_DEG;
			attitude.pitch += IMU_Data.G_Y*0.000520833f;//1/1920
			attitude.pitch = IMU_FILTER_COEFFICIENT * attitude.pitch + (1-IMU_FILTER_COEFFICIENT) *
								attitude_accel.pitch;	// Complementary filter for pitch
			break;
	}
}

void ALT_TxRxCpltCallback(){
	HAL_GPIO_WritePin(ALT_CS_GPIO_Port, ALT_CS_Pin, GPIO_PIN_SET);
	switch(ALT_Current_DMA_Transaction) {
		case ALT_WRITE_REG:
			break; // No additional processing is required on register write.
		case ALT_SINGLE_REG:
			break; // Not used yet (all single register reads use blocking mode)
		case ALT_PACKET: // Parse barometer Packet
			ALT_Raw.P = (ALT_SPI_ALTPacket_RX[ALT_OUT_PRES_H-0x02] << 16)
								+ (ALT_SPI_ALTPacket_RX[ALT_OUT_PRES_M-0x02] << 8)
								+ ALT_SPI_ALTPacket_RX[ALT_OUT_PRES_L-0x02];

			ALT_Raw.T = (ALT_SPI_ALTPacket_RX[ALT_OUT_TEMP_H-0x02] << 16)
								+ (ALT_SPI_ALTPacket_RX[ALT_OUT_TEMP_M-0x02] << 8)
								+ ALT_SPI_ALTPacket_RX[ALT_OUT_TEMP_L-0x02];

			ALT_Compensate();
			break;
	}
}


void LED_Test_Sequence(){
  HAL_GPIO_TogglePin(LED1_R_GPIO_Port, LED1_R_Pin);  // ON (pull low)
  HAL_Delay(200);
  HAL_GPIO_TogglePin(LED1_G_GPIO_Port, LED1_G_Pin);
  HAL_Delay(200);
  HAL_GPIO_TogglePin(LED2_R_GPIO_Port, LED2_R_Pin);
  HAL_Delay(200);
  HAL_GPIO_TogglePin(LED2_G_GPIO_Port, LED2_G_Pin);
  HAL_Delay(200);

  HAL_GPIO_TogglePin(LED1_R_GPIO_Port, LED1_R_Pin);
  HAL_Delay(200);
  HAL_GPIO_TogglePin(LED1_G_GPIO_Port, LED1_G_Pin);// OFF (release high)
  HAL_Delay(200);
  HAL_GPIO_TogglePin(LED2_R_GPIO_Port, LED2_R_Pin);
  HAL_Delay(200);
  HAL_GPIO_TogglePin(LED2_G_GPIO_Port, LED2_G_Pin);
  HAL_Delay(200);

  HAL_GPIO_TogglePin(LED1_R_GPIO_Port, LED1_R_Pin);
  HAL_GPIO_TogglePin(LED2_R_GPIO_Port, LED2_R_Pin);

}

void HAL_TIM_PeriodElapsedCallback(TIM_HandleTypeDef *htim){
	/* Used for blinking LEDs based on TIM3 */
	if(htim->Instance == TIM3){
		if(sensor_status == FATAL){
			LED1_G_Off();
			LED2_G_Off();
			LED1_R_Toggle();
			LED2_R_Toggle();
		} else if(sensor_status == MANUAL_ONLY) {
			LED1_G_On();
			LED2_G_Off();
			LED1_R_Off();
			LED2_R_Toggle();
		}
	}
}

void HAL_GPIO_EXTI_Callback(uint16_t EXTI_Pin){
	/* External interrupt callback */
	if(EXTI_Pin == ALT_INT_Pin){
		ALT_Read();
	}	else if(EXTI_Pin == IMU_INT1_Pin){
		IMU_Read();
	}
}
